graphql.query:
query {
  employees(
    filter: {
      department: "Engineering"
      isActive: true
    }
    sort: {
      field: NAME
      order: ASC
    }
    first: 5
  ) {
    edges {
      node {
        id
        employeeId
        name
        age
        class
        subjects
        department
        position
        email
        isActive
      }
      cursor
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    totalCount
  }
}

